13	pub(crate) enum CallExpressionPosition {
14	    /// At the start of a call chain.
15	    /// `of` in `of().test`
16	    Start,
17	
18	    /// Somewhere in the middle.
19	    ///
20	    /// `b` in `a.b().c()`
