fn fmt(src: &str) {
    let source_type = JsFileSource::tsx();
    let tree = parse(src, source_type, JsParserOptions::default());
    let options = JsFormatOptions::new(source_type)
        .with_indent_style(IndentStyle::Space)
        .with_line_width(LineWidth::try_from(80).unwrap());
    let doc = format_node(options, &tree.syntax()).unwrap();
    let result = doc.print().unwrap();
    println!("===INPUT===\n{}\n===OUTPUT===\n{}\n=====\n", src, result.as_code());
}

fn main() {
    // Single-line qualifying: static property accesses with empty lines
    fmt("a\n\n.b\n\n.c;");
    // Single-line qualifying: chain ending with a method call, no multiline
    fmt("a\n\n.b\n\n.c();");
    // Computed member access
    fmt("a\n\n.b\n\n[c];");
    // Multiline: many method calls with empty lines between groups
    fmt("something.execute().then()\n\n.then().catch();");
    // First group of tail has empty line before -> parent expansion
    fmt("foo\n\n.bar().baz().qux();");
}
